// Bump Chart — Time Series, route: jsx
// Source: original:gaps/bump-chart
//
// Self-contained: every local import is inlined below. Requires only d3, react.
// Generated by scripts/build-exemplars.mjs — edit src/gallery/, not this file.

import { useMemo } from 'react';
import * as d3 from 'd3';

// ---- inlined from bumpChart ----
// Programming-language popularity ranks, 2018-2025. Hardcoded plausible standings —
// the crossings are the point: Python passes JavaScript for #1, TypeScript climbs past
// Java, Rust passes PHP and then Java. Every column is a permutation of 1..7.
const languageRanks: {
  periods: string[];
  series: { name: string; ranks: number[] }[];
} = {
  periods: ['2018', '2019', '2020', '2021', '2022', '2023', '2024', '2025'],
  series: [
    { name: 'Python', ranks: [2, 2, 2, 2, 1, 1, 1, 1] },
    { name: 'JavaScript', ranks: [1, 1, 1, 1, 2, 2, 2, 2] },
    { name: 'TypeScript', ranks: [6, 5, 3, 3, 3, 3, 3, 3] },
    { name: 'C++', ranks: [4, 4, 5, 5, 5, 4, 4, 4] },
    { name: 'Java', ranks: [3, 3, 4, 4, 4, 5, 5, 6] },
    { name: 'Rust', ranks: [7, 7, 7, 6, 6, 6, 6, 5] },
    { name: 'PHP', ranks: [5, 6, 6, 7, 7, 7, 7, 7] }
  ]
};

const MARGIN = { top: 16, right: 96, bottom: 32, left: 96 };
const DOT_RADIUS = 3.5;

/** Ranks per series across ordered periods; ranks[i] is the rank in periods[i], 1 = top. */
export type Data = { periods: string[]; series: { name: string; ranks: number[] }[] };

export default function BumpChart({ data = languageRanks, width }: { data?: Data; width: number }) {
  const height = Math.round(width * 0.55);
  const innerWidth = width - MARGIN.left - MARGIN.right;
  const innerHeight = height - MARGIN.top - MARGIN.bottom;

  const x = useMemo(
    () => d3.scalePoint<string>().domain(data.periods).range([0, Math.max(innerWidth, 0)]),
    [data, innerWidth]
  );

  const maxRank = useMemo(() => d3.max(data.series, (s) => d3.max(s.ranks)) ?? 1, [data]);

  // Rank 1 maps to the top: the y domain is deliberately inverted relative to value charts.
  const y = useMemo(
    () => d3.scaleLinear().domain([1, maxRank]).range([0, Math.max(innerHeight, 0)]),
    [maxRank, innerHeight]
  );

  // The series that ends on top carries the accent; everything else recedes.
  const highlighted = useMemo(
    () => data.series.find((s) => s.ranks[s.ranks.length - 1] === 1)?.name,
    [data]
  );

  const series = useMemo(() => {
    const line = d3
      .line<number>()
      .x((_, i) => x(data.periods[i]) ?? 0)
      .y((rank) => y(rank))
      .curve(d3.curveBumpX);
    return data.series.map((s) => ({
      name: s.name,
      ranks: s.ranks,
      path: line(s.ranks) ?? '',
      color: s.name === highlighted ? 'var(--accent)' : 'var(--muted)'
    }));
  }, [data, x, y, highlighted]);

  if (width === 0) return null;

  return (
    <svg
      viewBox={`0 0 ${width} ${height}`}
      width="100%"
      height={height}
      role="img"
      aria-label="Bump chart of programming-language popularity ranks from 2018 to 2025, with Python overtaking JavaScript for first place"
    >
      <g transform={`translate(${MARGIN.left},${MARGIN.top})`}>
        {data.periods.map((period, i) => (
          <g key={period} transform={`translate(${x(period) ?? 0},0)`}>
            <line y1={0} y2={innerHeight} stroke="var(--line)" />
            {(x.step() >= 44 || i % 2 === 0) && (
            <text
              y={innerHeight + 20}
              textAnchor="middle"
              fontSize={11}
              fill="var(--muted)"
            >
              {period}
            </text>
            )}
          </g>
        ))}
        {series.map((s) => (
          <g key={s.name}>
            <path
              d={s.path}
              fill="none"
              stroke={s.color}
              strokeWidth={s.name === highlighted ? 2.5 : 1.5}
            />
            {s.ranks.map((rank, i) => (
              <circle
                key={data.periods[i]}
                cx={x(data.periods[i]) ?? 0}
                cy={y(rank)}
                r={s.name === highlighted ? DOT_RADIUS + 1 : DOT_RADIUS}
                fill={s.color}
              />
            ))}
            <text
              x={-10}
              y={y(s.ranks[0])}
              dy="0.32em"
              textAnchor="end"
              fontSize={11}
              fill={s.name === highlighted ? 'var(--accent)' : 'var(--text)'}
            >
              {`${s.ranks[0]}. ${s.name}`}
            </text>
            <text
              x={innerWidth + 10}
              y={y(s.ranks[s.ranks.length - 1])}
              dy="0.32em"
              textAnchor="start"
              fontSize={11}
              fill={s.name === highlighted ? 'var(--accent)' : 'var(--text)'}
            >
              {`${s.ranks[s.ranks.length - 1]}. ${s.name}`}
            </text>
          </g>
        ))}
      </g>
    </svg>
  );
}
